WITH scored AS (SELECT *, LAG(salary, 1, 0) OVER (PARTITION BY job_title ORDER BY hire_date, id) AS prev_salary, DENSE_RANK() OVER (PARTITION BY level, dept_id ORDER BY salary DESC) AS salary_dense_rank, ROW_NUMBER() OVER (PARTITION BY level ORDER BY salary, id) AS seq_no, PERCENT_RANK() OVER (PARTITION BY MONTH(hire_date), level ORDER BY salary) AS salary_percent_rank FROM employees WHERE MONTH(hire_date) IN (6, 7, 10)) SELECT s.id, s.dept_id, s.job_title, s.salary, s.hire_date, s.is_remote, s.level, s.prev_salary, s.salary_dense_rank, (SELECT SUM(t2.salary) FROM employees t2 WHERE t2.dept_id = s.dept_id) AS sum_employee_salary FROM scored s ORDER BY dept_id DESC NULLS LAST, level
